from author import *
b=[]
def add(a,n,ops,focus='viewport'):b.append(act(a,n,ops,focus))
add('A System You Can Inspect','Watch the fountain first. New dots rise, bend, shrink, and disappear. One effect comes from many short lives. This is an original teaching scene running inside the real Godot editor.',[call('reset'),setp('heading','A System You Can Inspect')])
add('A System You Can Inspect','Here is the actual scene tree. I add a Node Two D as an organizational child. The drawing script belongs to the root. Nodes organize the tool; the particle records describe each moving dot.',[dict(op='add',class_name='Node2D',name='EmissionOrigin',properties={'position':{'v2':[0,0]}},checkpoint=True),at(3,op='select')])
add('A System You Can Inspect','Open the script. Each record has position, velocity, age, and lifetime. Spawn creates that record. Draw turns it into a circle. The engine runs this code; the editor footage is not a rebuilt interface.',[script(26),at(6,op='select')],'code')
add('A System You Can Inspect','Birth Rate is twenty. Lifetime is two seconds. After the startup fills, the live counter settles near forty. Twenty arrivals each second, kept for two seconds: that is the population budget.',[setp('birth_rate',20),at(.3,**setp('lifetime',2)),at(.6,**call('reset'))])
add('Motion Has Separate Knobs','I turn on the diagnostic vectors. Mint shows velocity; purple shows acceleration. The particle moves along its velocity. Gravity changes that velocity. Two different jobs, even when the arrows share one dot.',[setp('heading','Motion Has Separate Knobs'),at(.25,**setp('birth_rate',3)),at(.5,**setp('vectors',True)),at(.75,**call('reset'))])
add('Motion Has Separate Knobs','Set gravity to zero. The trajectories become straight. Restore positive gravity and they bend downward. In this two-dimensional scene, positive Y points down. The launch velocity begins upward, with negative Y.',[setp('gravity',0),at(5,**setp('gravity',180))])
add('Motion Has Separate Knobs','These are the update lines. Velocity gains acceleration times delta. Position gains velocity times delta. Delta is elapsed time in seconds, so the units stay tied to time instead of to a frame count.',[script(37),at(6,op='select')],'code')
add('Motion Has Separate Knobs','Increase launch speed from two hundred sixty to three hundred forty. The next particles climb farther before gravity turns them around. The change enters at birth; existing particles keep the velocity they already have.',[setp('launch_speed',340),at(.2,**setp('vectors',False)),at(.4,**setp('birth_rate',20)),at(.6,**call('reset'))])
add('Age Controls The Exit','Now shorten lifetime from two seconds to one. Reset gives every dot the same rule immediately. The trail ends sooner and the live count falls toward twenty. Birth rate did not change.',[setp('heading','Age Controls The Exit'),at(.2,**setp('launch_speed',260)),at(.4,**setp('lifetime',1)),at(.6,**call('reset'))])
add('Age Controls The Exit','Switch fading and shrinking off. Dots now disappear abruptly at their lifetime. Turn both back on and the exit becomes a transition. Appearance reads normalized age: age divided by that particle’s own lifetime.',[setp('fade',False),at(.2,**setp('shrink',False)),at(5,**setp('fade',True)),at(5.2,**setp('shrink',True))])
add('Age Controls The Exit','Here is a deliberately broken version. Cleanup is off. Dead records remain in the array, so the live counter keeps growing even after the visible dots fade away. Invisible does not mean removed.',[setp('cleanup',False),at(.2,**call('reset'))])
add('Age Controls The Exit','Restore cleanup. The reverse loop can remove expired entries without skipping the next record. The count returns to its bounded population. This lab also caps storage at six hundred to contain the deliberate fault.',[setp('cleanup',True),at(4,**script(40)),at(8,op='select')])
add('Variation And The Emitter','Set spread to zero. Every launch points the same way and the fountain collapses into a narrow column. Randomness is not the system itself. It is a controlled variation applied when particles are born.',[setp('heading','Variation And The Emitter'),at(.2,**setp('lifetime',2)),at(.4,**setp('spread',0)),at(.6,**call('reset'))])
add('Variation And The Emitter','Open spread to thirty-five degrees. Each birth samples a direction inside the range. The fountain widens, while lifetime and gravity stay fixed. A repeatable seed helps compare one parameter without changing every random choice.',[setp('spread',35),at(.3,**call('reset'))])
add('Variation And The Emitter','Move the emitter. New particles start at its current position; older particles continue from their stored positions. That separation makes a trail. Dragging every old particle with the emitter would produce a different effect.',[setp('move_emitter',True)])
add('Variation And The Emitter','Add wind to the right. The trajectories curve sideways because wind enters the acceleration vector. Position, launch direction, gravity, and wind are separate controls. Change one and watch the consequence before changing another.',[setp('wind',120)])
add('A Burst Is A Schedule','Stop continuous births and reset. One burst now creates forty particles together. Watch the complete effect die out. A burst changes when particles are born; it does not require a different motion equation.',[setp('heading','A Burst Is A Schedule'),at(.2,**setp('birth_rate',0)),at(.4,**setp('wind',0)),at(.6,**setp('move_emitter',False)),at(.8,**call('reset')),at(1,**call('burst')),at(5,**call('burst'))])
add('A Burst Is A Schedule','Trigger the burst again. The new records get fresh ages and positions. An effect should respond to an event, such as an impact, while a continuous effect should follow a condition that can turn off.',[call('burst'),at(5,**call('burst'))])
add('A Burst Is A Schedule','The built-in version packages those responsibilities. This is a real G P U Particles Two D node with a texture and a Particle Process Material. Godot owns the simulation; the Inspector exposes its controls.',[dict(op='open',path='res://builtin_fountain.tscn'),at(1,**setp('position',{'v2':[0,0]},'Fountain')),at(1.3,op='zoom',node='Fountain')])
add('A Burst Is A Schedule','Increase Amount from forty to eighty. More particles occupy the built-in effect. Here Amount is a population setting, not births per second. For a steady emitter, amount divided by lifetime gives its nominal emission rate.',[setp('amount',80,'Fountain')])
add('Build A Testable Effect','Switch One Shot on and set Explosiveness to one. Restart releases the group together. The visible change is timing, not a new texture. In a reusable scene, let the final layer finish before removing its owner.',[setp('one_shot',True,'Fountain'),at(.3,**setp('explosiveness',1,'Fountain')),at(.6,op='call',node='Fountain',method='restart'),at(5,op='call',node='Fountain',method='restart')])
add('Build A Testable Effect','Return to the original lab. A larger circle covers more pixels even with the same particle count. This demonstrates coverage, not a measured frame-time cost. Performance needs its own instrument and a repeatable scene.',[dict(op='open',path='res://lesson.tscn'),at(1,**setp('birth_rate',20)),at(1.3,**setp('radius',24)),at(1.6,**call('reset')),at(1.9,op='zoom')])
add('Build A Testable Effect','Keep the experiment readable. Reset the counter, return to small particles, and change lifetime alone. Save the source and the settings that produced the picture. Otherwise a convincing clip is difficult to reproduce.',[setp('heading','Build A Testable Effect'),at(.2,**setp('radius',8)),at(.4,**setp('lifetime',2)),at(.6,**setp('spread',28)),at(.8,**setp('birth_rate',20)),at(1,**call('reset')),at(5,op='save',checkpoint=True)])
add('Build A Testable Effect','The teaching tool is now inspectable: source, live counters, exported controls, and a built-in comparison. These actions were scripted in the actual editor. The result remains an editable project, not just a movie of orange dots.',[script(1),at(5,op='select'),at(5.2,op='save',checkpoint=True)],'code')
d=dict(slug='claude-liam-lecture-what-is-a-particle-system',title='What Is a Particle System?',payoff='Build the rules behind a moving effect',summary='Build a small particle system and test the rules behind its motion.',framing='How do simple rules make an effect? A particle system is a changing population, not one animated picture. We will expose the rules in Godot.',question='How do simple pictures\nmake an effect?',trigger='pictures',replacement='rules',terms=[dict(term='Node',meaning='An object in the scene tree'),dict(term='Vector',meaning='A direction and a magnitude'),dict(term='Delta',meaning='Elapsed time for one update'),dict(term='Resource',meaning='Reusable data held by a node')],body=b,recap=['A system gives many particles short lives.','Velocity and acceleration have separate jobs.','Age controls appearance and removal.','The emitter chooses each starting state.','Bursts and streams use different birth schedules.','A reproducible test connects settings to motion.'],prompt='Build a fountain with a fixed birth rate and lifetime. Change wind alone, then change lifetime alone. Record each result and explain the live count. Keep the source and both settings.',checks=['Check: wind changes the path, not the birth rate.','Check: the live population stays bounded.'],coverage='The source treatment covers particle state, birth/update/draw/death, time-based integration, lifetime and appearance, bounded cleanup, emission rate and population, controlled random starts, moving emitter and wind, stream versus burst, built-in Godot nodes, reproducible source and performance limits. Six acts, four beats each.',facts='The original GDScript uses p.v += acceleration * delta, p.p += p.v * delta, reverse removal after age >= life. Population estimate is rate × lifetime for this steady emitter. Godot GPUParticles2D Amount is a count, not a rate. Missing cleanup is a labeled seeded fault. The 600-record cap limits the deliberate failure. No GPU performance measurement is claimed.')
Path('film1.json').write_text(json.dumps(d,indent=2));author(d)
